      "name": "Net revenue by customer country (last 90 days)",
      "description": "Standard revenue-by-geo cut used in weekly business review.",
      "language": "SQL",
      "statement": "SELECT c.country, SUM(r.net_amount_usd) AS net_revenue\nFROM analytics.marts.fct_revenue r\nJOIN analytics.marts.dim_customers c ON c.customer_id = r.customer_id\nWHERE r.revenue_date >= DATEADD(day, -90, CURRENT_DATE)\nGROUP BY 1 ORDER BY 2 DESC;"
    }
  ]
}

